<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue'
import { api, ApiError, type EmployeeCreateCommand } from '../api'
import { useSession } from '../session'
import { captureRequestScope } from '../request-scope'
const auth=useSession(),emit=defineEmits<{created:[id:string]}>(),account=ref(''),name=ref(''),password=ref(''),busy=ref(false),message=ref(''),observed=ref(false),pending=ref<Omit<EmployeeCreateCommand,'initialPassword'>|null>(null)
let originalPassword='',alive=true
const allowed=computed(()=>auth.identity?.realm==='TENANT'&&auth.identity.permissions.includes('identity.employee.manage'))
const storageKey=computed(()=>`ias.employee.create.${auth.identity?.tenant?.id||''}.${auth.identity?.userId||''}`)
watch(storageKey,()=>{pending.value=null;originalPassword='';password.value='';observed.value=false;try{const raw=sessionStorage.getItem(storageKey.value);if(raw){const p=JSON.parse(raw);if(typeof p.operationId==='string'&&typeof p.account==='string'&&typeof p.displayName==='string')pending.value=p}}catch{message.value='无法读取原操作，请联系管理员核验。'}},{immediate:true})
function clear(){sessionStorage.removeItem(storageKey.value);pending.value=null;password.value='';originalPassword='';observed.value=false}
async function send(){if(!allowed.value||!auth.csrf||busy.value)return;if(!pending.value){if(!/^[A-Za-z0-9._-]{1,100}$/.test(account.value)||!name.value.trim()||name.value!==name.value.trim()||Array.from(name.value).length>50||Array.from(password.value).length<12||Array.from(password.value).length>128){message.value='请检查账号、姓名和至少 12 位的初始密码。';return}pending.value={operationId:crypto.randomUUID(),account:account.value,displayName:name.value};originalPassword=password.value;sessionStorage.setItem(storageKey.value,JSON.stringify(pending.value))}else if(!observed.value||!originalPassword)return
 const meta={...pending.value},command={...meta,initialPassword:originalPassword},scope=captureRequestScope(auth,()=>alive&&pending.value?.operationId===meta.operationId);busy.value=true;message.value='';try{const result=await api.createEmployee(command,auth.csrf.token);if(!scope.current())return;if(result.operationId!==meta.operationId||result.account!==meta.account.toLowerCase())throw Error('回执不匹配');clear();message.value='员工已创建，首次登录需修改密码。';emit('created',result.userId)}catch(e){if(!scope.current())return;if(e instanceof ApiError&&e.status>0&&e.status<500&&e.code!=='OPERATION_ALREADY_OBSERVED'){clear();message.value=`创建未完成：${e.code}。`}else{observed.value=false;message.value='结果尚未确认，请先查询原操作。'}}finally{if(scope.current()||!pending.value)busy.value=false}}
async function query(){if(!pending.value||busy.value)return;const meta={...pending.value},scope=captureRequestScope(auth,()=>alive&&pending.value?.operationId===meta.operationId);busy.value=true;try{const result=await api.employeeCreateOperation(meta.operationId);if(!scope.current())return;if(result.operationId!==meta.operationId||result.account!==meta.account.toLowerCase())throw Error('回执不匹配');clear();message.value='原创建操作已完成。';emit('created',result.userId)}catch(e){if(!scope.current())return;if(e instanceof ApiError&&e.status===404&&e.code==='OPERATION_NOT_OBSERVED'){observed.value=true;message.value=originalPassword?'尚未观察到原操作，可显式按原参数继续。':'尚未观察到原操作；刷新后初始密码未保留，请联系管理员核验。'}else message.value='原操作结果无法确认，请稍后再查。'}finally{if(scope.current()||!pending.value)busy.value=false}}
onUnmounted(()=>{alive=false;originalPassword='';password.value=''})
</script>
<template><section v-if="allowed" class="panel"><h2>创建员工</h2><p>新员工首次登录须修改初始密码；授权范围需单独配置。</p><template v-if="!pending"><label>账号 <input v-model="account" maxlength="100" autocomplete="off"></label><label>姓名 <input v-model="name" maxlength="50"></label><label>初始密码 <input v-model="password" type="password" autocomplete="new-password"></label><button :disabled="busy" @click="send">确认创建员工</button></template><template v-else><p>原操作：{{ pending.operationId }} · 账号：{{ pending.account }} · 姓名：{{ pending.displayName }}</p><button :disabled="busy" @click="query">查询原创建操作</button><button v-if="observed && originalPassword" :disabled="busy" @click="send">显式按原参数继续</button></template><p v-if="message" role="status">{{ message }}</p></section></template>
